window.QDATA[1] = [
{id:"clf-j1-1",q:"Une entreprise veut que son application reste disponible si un datacenter entier tombe en panne. Quelle conception AWS répond à ce besoin au moindre effort ?",choices:["Déployer l'application dans plusieurs zones de disponibilité d'une même région","Déployer l'application sur une seule instance EC2 de grande taille","Déployer l'application dans plusieurs edge locations","Déployer l'application dans une Local Zone"],answer:0,exp:"Les AZ ne partagent aucun point de défaillance unique : répartir sur plusieurs AZ assure la haute disponibilité."},
{id:"clf-j1-2",q:"Quelle affirmation décrit correctement une zone de disponibilité (AZ) ?",choices:["Un ou plusieurs datacenters avec alimentation, réseau et refroidissement redondants","Une zone géographique contenant plusieurs régions","Un point de présence utilisé par CloudFront pour mettre en cache du contenu","Un serveur AWS installé dans le datacenter du client"],answer:0,exp:"C'est la définition officielle d'une AZ."},
{id:"clf-j1-3",q:"Une loi impose qu'une entreprise conserve les données de ses clients dans son pays. Quel facteur guide en priorité le choix de la région AWS ?",choices:["La conformité et la souveraineté des données","Le prix des instances EC2","Le nombre de services disponibles","La proximité des edge locations"],answer:0,exp:"Une exigence légale passe avant tout autre critère de choix de région."},
{id:"clf-j1-4",q:"Quels sont DEUX avantages d'utiliser plusieurs régions AWS ? (2 réponses)",choices:["Reprise après sinistre en cas de panne régionale","Réduction de la latence pour des utilisateurs répartis dans le monde","Suppression totale des frais de transfert de données","Gestion automatique des correctifs de l'OS des instances","Accès gratuit au plan de support Enterprise"],answer:0,exp:"Une seconde région permet de redémarrer si toute une région est indisponible."},
{id:"clf-j1-5",q:"Quel service s'appuie sur les edge locations pour réduire la latence de diffusion de contenu web ?",choices:["Amazon CloudFront","Amazon EBS","AWS Direct Connect","Amazon RDS"],answer:0,exp:"CloudFront est le CDN d'AWS, il met en cache le contenu dans les edge locations."},
{id:"clf-j1-6",q:"Une entreprise a besoin de faire tourner des services AWS dans son propre datacenter pour des raisons de latence locale. Quel service choisir ?",choices:["AWS Outposts","AWS Local Zones","AWS Wavelength","Amazon CloudFront"],answer:0,exp:"Outposts installe du matériel AWS directement chez le client."},
{id:"clf-j1-7",q:"Une application de jeu mobile doit offrir une latence ultra-faible aux utilisateurs connectés en 5G. Quel service est conçu pour ce cas ?",choices:["AWS Wavelength","AWS Outposts","AWS Direct Connect","Amazon Lightsail"],answer:0,exp:"Wavelength intègre le calcul AWS dans les réseaux 5G des opérateurs."},
{id:"clf-j1-8",q:"Lequel de ces services est global (non lié à une région) ?",choices:["AWS IAM","Amazon EC2","Amazon RDS","Amazon EBS"],answer:0,exp:"IAM est global : un user ou une policy vaut pour toutes les régions."},
{id:"clf-j1-9",q:"Une entreprise veut des temps de réponse de quelques millisecondes pour des utilisateurs situés dans une grande ville éloignée de toute région AWS. Quelle option convient ?",choices:["AWS Local Zones","Une zone de disponibilité supplémentaire","AWS Snowball","AWS Global Accelerator uniquement"],answer:0,exp:"Les Local Zones étendent une région au plus près d'une grande ville."},
{id:"clf-j1-10",q:"Combien de zones de disponibilité une nouvelle région AWS comporte-t-elle au minimum ?",choices:["3","1","2","6"],answer:0,exp:"AWS conçoit ses nouvelles régions avec au moins 3 AZ."},
{id:"clf-j1-11",q:"Une entreprise exécute une base de données en mémoire qui nécessite beaucoup de RAM. Quelle famille d'instances EC2 choisir ?",choices:["Optimisée pour la mémoire (R, X)","Optimisée pour le calcul (C)","Optimisée pour le stockage (I, D)","Calcul accéléré (P, G)"],answer:0,exp:"Les familles R et X offrent un ratio mémoire/CPU élevé."},
{id:"clf-j1-12",q:"Quelle famille d'instances convient le mieux à l'encodage vidéo et aux serveurs de jeu, très gourmands en CPU ?",choices:["Optimisée pour le calcul","Usage général","Optimisée pour la mémoire","Optimisée pour le stockage"],answer:0,exp:"Les instances C sont faites pour les charges limitées par le CPU."},
{id:"clf-j1-13",q:"Une équipe entraîne des modèles de deep learning. Quelle famille d'instances est la plus adaptée ?",choices:["Calcul accéléré (GPU)","Usage général","Optimisée pour le stockage","Instances T avec crédits CPU"],answer:0,exp:"L'entraînement de modèles exploite les GPU ou les puces dédiées (P, Trn)."},
{id:"clf-j1-14",q:"Un entrepôt de données traite de gros volumes en lecture/écriture séquentielle sur disque local. Quelle famille choisir ?",choices:["Optimisée pour le stockage","Optimisée pour le calcul","Calcul accéléré","Usage général"],answer:0,exp:"Les familles I et D offrent de fortes performances d'E/S sur disque local."},
{id:"clf-j1-15",q:"Qu'est-ce qu'une AMI (Amazon Machine Image) ?",choices:["Un modèle contenant l'OS et les logiciels pour lancer une instance","Un type de volume de stockage EBS","Une règle de pare-feu attachée à une instance","Un plan de tarification EC2"],answer:0,exp:"L'AMI est l'image de départ d'une instance."},
{id:"clf-j1-16",q:"Quel service permet de lancer un serveur privé virtuel simple, avec un prix mensuel fixe et prévisible, pour un petit site WordPress ?",choices:["Amazon Lightsail","Amazon EC2 Dedicated Hosts","AWS Batch","Amazon EKS"],answer:0,exp:"Lightsail cible les besoins simples avec un forfait mensuel."},
{id:"clf-j1-17",q:"Une fonction doit redimensionner une image chaque fois qu'un fichier est déposé dans un bucket S3, sans gérer de serveur. Quel service choisir ?",choices:["AWS Lambda","Amazon EC2","Amazon Lightsail","AWS Outposts"],answer:0,exp:"Lambda exécute du code en réponse à un événement S3, sans serveur."},
{id:"clf-j1-18",q:"Quelle est la durée d'exécution maximale d'une fonction AWS Lambda ?",choices:["15 minutes","5 minutes","1 heure","Illimitée"],answer:0,exp:"Une exécution Lambda est plafonnée à 15 minutes."},
{id:"clf-j1-19",q:"Comment AWS Lambda est-il facturé ?",choices:["Au nombre de requêtes et à la durée d'exécution","À l'heure, que la fonction tourne ou non","Au nombre d'instances EC2 provisionnées","Par un forfait mensuel fixe"],answer:0,exp:"On paie les invocations et le temps de calcul, à la milliseconde."},
{id:"clf-j1-20",q:"Un traitement de données dure environ 3 heures et tourne une fois par nuit. Quelle option NE convient PAS ?",choices:["AWS Lambda","Amazon EC2","AWS Batch","AWS Fargate"],answer:0,exp:"Lambda est limité à 15 minutes par exécution : impossible pour 3 heures d'un seul tenant."},
{id:"clf-j1-21",q:"Un développeur veut déployer une application web en déposant simplement son code, sans configurer EC2, load balancer ni Auto Scaling. Quel service utiliser ?",choices:["AWS Elastic Beanstalk","AWS CloudFormation","Amazon EC2","AWS Direct Connect"],answer:0,exp:"Beanstalk (PaaS) crée et gère l'infrastructure à partir du code."},
{id:"clf-j1-22",q:"Avec Elastic Beanstalk, qui reste responsable du code de l'application ?",choices:["Le client","AWS","Un partenaire AWS obligatoirement","Le support AWS Enterprise"],answer:0,exp:"Beanstalk gère l'infra, le code reste au client."},
{id:"clf-j1-23",q:"Une équipe scientifique doit lancer des milliers de simulations en parallèle, avec un provisionnement automatique des ressources. Quel service est conçu pour cela ?",choices:["AWS Batch","Amazon Lightsail","AWS Elastic Beanstalk","Amazon CloudFront"],answer:0,exp:"Batch planifie et exécute des traitements par lots à grande échelle."},
{id:"clf-j1-24",q:"Dans quel modèle de service se situe Amazon EC2 ?",choices:["IaaS (Infrastructure as a Service)","PaaS (Platform as a Service)","SaaS (Software as a Service)","FaaS uniquement"],answer:0,exp:"EC2 fournit des machines virtuelles dont le client gère l'OS."},
{id:"clf-j1-25",q:"Quel avantage du cloud Amazon EC2 Auto Scaling apporte-t-il directement ?",choices:["L'élasticité","La conformité réglementaire","Le chiffrement des données","La réduction de la latence DNS"],answer:0,exp:"Auto Scaling ajoute ou retire des instances selon la demande : c'est l'élasticité."},
{id:"clf-j1-26",q:"Une boutique en ligne connaît des pics de trafic imprévisibles. Comment éviter de payer des serveurs inutilisés en période calme ?",choices:["Utiliser Auto Scaling pour ajuster le nombre d'instances à la demande","Provisionner des instances pour le pic maximum en permanence","Acheter des hôtes dédiés","Utiliser une seule très grande instance"],answer:0,exp:"Auto Scaling réduit la capacité quand la charge baisse."},
{id:"clf-j1-27",q:"Dans un groupe Auto Scaling, que se passe-t-il quand une instance échoue au contrôle de santé ?",choices:["Elle est remplacée automatiquement","Le groupe est supprimé","AWS facture une pénalité","Le trafic est redirigé vers une autre région"],answer:0,exp:"Auto Scaling remplace les instances défaillantes pour maintenir la capacité."},
{id:"clf-j1-28",q:"Quels paramètres définissent la taille d'un groupe Auto Scaling ? (2 réponses)",choices:["Capacité minimale et maximale","Capacité souhaitée","Nombre d'edge locations","Classe de stockage S3","Plan de support AWS"],answer:0,exp:"Le minimum et le maximum bornent le nombre d'instances."},
{id:"clf-j1-29",q:"Quel est le rôle principal d'Elastic Load Balancing ?",choices:["Répartir le trafic entrant entre plusieurs cibles saines","Stocker les sessions utilisateurs","Chiffrer les volumes EBS","Ajouter des instances quand la charge augmente"],answer:0,exp:"Le load balancer distribue les requêtes et écarte les cibles en échec."},
{id:"clf-j1-30",q:"Une application web doit router les requêtes /api vers un groupe de serveurs et /images vers un autre. Quel load balancer choisir ?",choices:["Application Load Balancer","Network Load Balancer","Gateway Load Balancer","Classic Load Balancer avec IP fixe"],answer:0,exp:"L'ALB (couche 7) sait router selon le chemin d'URL."},
{id:"clf-j1-31",q:"Une application TCP doit traiter des millions de requêtes par seconde avec une latence très faible. Quel load balancer convient ?",choices:["Network Load Balancer","Application Load Balancer","Gateway Load Balancer","Amazon Route 53"],answer:0,exp:"Le NLB (couche 4) est conçu pour les performances extrêmes en TCP/UDP."},
{id:"clf-j1-32",q:"Une entreprise veut faire passer tout son trafic par un pare-feu virtuel d'un éditeur tiers. Quel type de load balancer est prévu pour cela ?",choices:["Gateway Load Balancer","Application Load Balancer","Network Load Balancer","AWS WAF"],answer:0,exp:"Le GWLB déploie et répartit le trafic vers des appliances tierces."},
{id:"clf-j1-33",q:"Quelle combinaison offre à la fois haute disponibilité et élasticité pour une application web sur EC2 ?",choices:["Elastic Load Balancing + Auto Scaling sur plusieurs AZ","Une instance EC2 + un volume EBS","CloudFront + une seule instance","Route 53 + une seule AZ"],answer:0,exp:"Le load balancer répartit et Auto Scaling ajuste le nombre d'instances dans plusieurs AZ."},
{id:"clf-j1-34",q:"Où une entreprise doit-elle stocker ses images Docker pour les utiliser avec Amazon ECS ?",choices:["Amazon ECR","Amazon EFS","AWS CodePipeline","Amazon S3 Glacier"],answer:0,exp:"ECR est le registre d'images de conteneurs d'AWS."},
{id:"clf-j1-35",q:"Une entreprise utilise déjà Kubernetes sur site et veut le même outil dans AWS, en managé. Quel service choisir ?",choices:["Amazon EKS","Amazon ECS","AWS Elastic Beanstalk","AWS Lambda"],answer:0,exp:"EKS est le Kubernetes managé d'AWS."},
{id:"clf-j1-36",q:"Une équipe veut exécuter des conteneurs sans gérer ni mettre à jour les instances EC2 sous-jacentes. Quel service utiliser ?",choices:["AWS Fargate","Amazon EC2 Auto Scaling","Amazon Lightsail","AWS Outposts"],answer:0,exp:"Fargate exécute les conteneurs d'ECS ou EKS sans serveurs à gérer."},
{id:"clf-j1-37",q:"Quel service orchestre des conteneurs Docker de manière simple et très intégrée à AWS, sans Kubernetes ?",choices:["Amazon ECS","Amazon EKS","Amazon ECR","AWS Batch"],answer:0,exp:"ECS est l'orchestrateur maison d'AWS."},
{id:"clf-j1-38",q:"Quelle affirmation sur AWS Fargate est correcte ?",choices:["C'est un moteur de calcul sans serveur pour ECS et EKS","C'est un registre d'images Docker","C'est un service de base de données","C'est un CDN"],answer:0,exp:"Fargate exécute les conteneurs sans que le client gère les serveurs."},
{id:"clf-j1-39",q:"Une entreprise gère elle-même Docker sur des instances EC2 et veut se décharger de la gestion des clusters et de leur maintenance. Quelle option réduit le plus l'effort ?",choices:["Amazon ECS sur AWS Fargate","Ajouter des instances EC2 plus grosses","Amazon RDS","Amazon Athena"],answer:0,exp:"ECS orchestre et Fargate supprime la gestion des serveurs."},
{id:"clf-j1-40",q:"Quels services utilisent les edge locations AWS ? (2 réponses)",choices:["Amazon CloudFront","Amazon Route 53","Amazon RDS","Amazon EBS","AWS Batch"],answer:0,exp:"CloudFront met en cache le contenu dans les edge locations."},
{id:"clf-j1-41",q:"Pourquoi déployer une application sur plusieurs AZ plutôt que sur une seule ?",choices:["Pour qu'une panne d'AZ n'arrête pas l'application","Pour réduire la facture de transfert de données","Pour respecter automatiquement le RGPD","Pour éviter de configurer des security groups"],answer:0,exp:"Les AZ sont isolées : si l'une tombe, les autres continuent."},
{id:"clf-j1-42",q:"Quel avantage de l'infrastructure mondiale AWS permet de lancer une application dans un nouveau pays en quelques minutes ?",choices:["Le déploiement mondial rapide grâce aux régions existantes","Les remises sur volume","Le modèle de responsabilité partagée","AWS Artifact"],answer:0,exp:"Les régions existent déjà : on y déploie en quelques clics, sans construire de datacenter."},
{id:"clf-j1-43",q:"Quelle option permet d'exécuter automatiquement un script de configuration au premier démarrage d'une instance EC2 ?",choices:["Les user data","Un security group","Une Elastic IP","AWS Artifact"],answer:0,exp:"Les user data contiennent un script exécuté au lancement."},
{id:"clf-j1-44",q:"Un serveur web a une charge modérée avec des pics occasionnels de CPU. Quelle famille d'instances est la plus économique ?",choices:["Instances T à performances évolutives","Instances C optimisées pour le calcul","Instances P à GPU","Instances X optimisées pour la mémoire"],answer:0,exp:"Les instances T accumulent des crédits CPU pour absorber les pics, à petit prix."},
{id:"clf-j1-45",q:"Un client veut une solution où il ne gère ni serveur, ni OS, ni mise à l'échelle, et paie uniquement à l'exécution. Quels services correspondent ? (2 réponses)",choices:["AWS Lambda","AWS Fargate","Amazon EC2","Amazon Lightsail","AWS Outposts"],answer:0,exp:"Lambda est entièrement sans serveur."},
{id:"clf-j1-46",q:"Un load balancer détecte qu'une instance ne répond plus. Que fait-il ?",choices:["Il cesse de lui envoyer du trafic","Il redémarre l'instance","Il en crée une copie dans une autre région","Il ouvre un ticket au support AWS"],answer:0,exp:"Grâce aux contrôles de santé, il n'envoie plus de requêtes à une cible malsaine."},
{id:"clf-j1-47",q:"Quel est le lien entre Auto Scaling et Elastic Load Balancing ?",choices:["Auto Scaling ajuste le nombre d'instances, le load balancer répartit le trafic entre elles","Ce sont deux noms du même service","Auto Scaling remplace le load balancer","Le load balancer décide de la taille des instances"],answer:0,exp:"Les deux se complètent : combien d'instances, et à laquelle envoyer chaque requête."},
{id:"clf-j1-48",q:"Une entreprise veut tester une nouvelle application auprès d'utilisateurs en Asie sans investir dans du matériel. Quel avantage du cloud cela illustre-t-il ?",choices:["Devenir mondial en quelques minutes","Remplacer les dépenses variables par des dépenses fixes","Augmenter les coûts de datacenter","Deviner la capacité à l'avance"],answer:0,exp:"On déploie dans une région asiatique sans rien acheter."},
{id:"clf-j1-49",q:"Quelle affirmation compare correctement ECS et EKS ?",choices:["Les deux orchestrent des conteneurs, EKS utilise Kubernetes","ECS stocke des images, EKS les exécute","EKS est sans serveur, ECS ne l'est jamais","ECS est réservé à Windows"],answer:0,exp:"Ce sont deux orchestrateurs : EKS est basé sur Kubernetes, ECS est propre à AWS."},
{id:"clf-j1-50",q:"Quel service choisir pour exécuter du code en réponse à une requête API, avec une facturation à la milliseconde et aucune instance à gérer ?",choices:["AWS Lambda derrière Amazon API Gateway","Amazon EC2 derrière un Network Load Balancer","Amazon Lightsail","AWS Batch"],answer:0,exp:"API Gateway reçoit la requête et déclenche Lambda, sans serveur."}
];

window.QDATA[2] = [
{id:"clf-j2-1",q:"Quel type de stockage est Amazon S3 ?",choices:["Stockage objet","Stockage en bloc","Système de fichiers partagé NFS","Base de données relationnelle"],answer:0,exp:"S3 stocke des objets (fichier + métadonnées) dans des buckets."},
{id:"clf-j2-2",q:"Quelle durabilité Amazon S3 Standard est-il conçu pour offrir ?",choices:["99,999999999 % (11 neuf)","99,9 %","99,99 %","100 %"],answer:0,exp:"S3 est conçu pour 11 neuf de durabilité."},
{id:"clf-j2-3",q:"Une entreprise ne connaît pas à l'avance la fréquence d'accès à ses données, et elle change souvent. Quelle classe S3 optimise automatiquement les coûts ?",choices:["S3 Intelligent-Tiering","S3 Standard-IA","S3 One Zone-IA","S3 Glacier Deep Archive"],answer:0,exp:"Intelligent-Tiering déplace les objets entre niveaux selon leur usage réel."},
{id:"clf-j2-4",q:"Des documents doivent être conservés 10 ans pour raisons légales et ne seront presque jamais consultés. Quelle classe est la moins chère ?",choices:["S3 Glacier Deep Archive","S3 Standard","S3 Intelligent-Tiering","S3 Standard-IA"],answer:0,exp:"Deep Archive est la classe la moins chère, adaptée aux archives long terme."},
{id:"clf-j2-5",q:"Des données peu consultées doivent pouvoir être récupérées en millisecondes. Elles sont faciles à recréer si elles sont perdues. Quelle classe est la plus économique ?",choices:["S3 One Zone-IA","S3 Standard","S3 Glacier Flexible Retrieval","S3 Glacier Deep Archive"],answer:0,exp:"One Zone-IA est moins chère car stockée dans une seule AZ, acceptable pour des données recréables."},
{id:"clf-j2-6",q:"Des archives médicales sont consultées environ une fois par trimestre, mais doivent alors être disponibles immédiatement. Quelle classe choisir ?",choices:["S3 Glacier Instant Retrieval","S3 Glacier Deep Archive","S3 Glacier Flexible Retrieval","S3 Standard"],answer:0,exp:"Instant Retrieval offre un accès en millisecondes à un prix d'archive."},
{id:"clf-j2-7",q:"Quelle fonctionnalité S3 déplace automatiquement les objets vers une classe moins chère après 30 jours, puis les supprime après 5 ans ?",choices:["Les règles de cycle de vie (lifecycle)","Le versioning","La réplication entre régions","S3 Transfer Acceleration"],answer:0,exp:"Les règles de cycle de vie automatisent transitions et expirations."},
{id:"clf-j2-8",q:"Un utilisateur supprime par erreur un fichier important dans S3. Quelle fonctionnalité aurait permis de le récupérer ?",choices:["Le versioning S3","S3 Transfer Acceleration","Les règles de cycle de vie","S3 One Zone-IA"],answer:0,exp:"Avec le versioning, une suppression ajoute un marqueur et l'ancienne version reste récupérable."},
{id:"clf-j2-9",q:"Quel service S3 permet d'héberger un site web statique (HTML, CSS, images) sans serveur ?",choices:["L'hébergement de site web statique S3","Amazon EBS","Amazon EC2 avec Apache","AWS Storage Gateway"],answer:0,exp:"S3 peut servir directement des sites statiques."},
{id:"clf-j2-10",q:"Quelle affirmation sur les noms de bucket S3 est vraie ?",choices:["Ils doivent être uniques dans le monde entier","Ils doivent être uniques uniquement dans la région","Ils peuvent être identiques entre deux comptes","Ils sont attribués automatiquement par AWS"],answer:0,exp:"Un nom de bucket est unique sur l'ensemble d'AWS (dans la même partition)."},
{id:"clf-j2-11",q:"Des utilisateurs du monde entier envoient de gros fichiers vers un bucket S3 situé en Europe et les transferts sont lents. Quelle fonctionnalité aide ?",choices:["S3 Transfer Acceleration","S3 One Zone-IA","Le versioning S3","Les politiques de cycle de vie"],answer:0,exp:"Transfer Acceleration fait entrer les données par l'edge location la plus proche."},
{id:"clf-j2-12",q:"Quelle est la taille maximale d'un objet unique dans Amazon S3 ?",choices:["5 To","5 Go","160 To","Illimitée"],answer:0,exp:"Un objet S3 peut atteindre 5 To."},
{id:"clf-j2-13",q:"Quels éléments influencent le coût de S3 ? (2 réponses)",choices:["La quantité de données stockées et la classe de stockage","Le volume de données transférées vers internet","Le nombre de zones de disponibilité de la région","Le nombre d'utilisateurs IAM du compte","Le plan de support choisi"],answer:0,exp:"On paie au Go stocké, selon la classe."},
{id:"clf-j2-14",q:"Quel service fournit un stockage en bloc persistant pour une instance EC2 ?",choices:["Amazon EBS","Amazon S3","Amazon EFS","Le stockage d'instance"],answer:0,exp:"EBS est un disque réseau persistant attaché à une instance."},
{id:"clf-j2-15",q:"Que deviennent les données d'un stockage d'instance (instance store) quand l'instance est arrêtée ?",choices:["Elles sont perdues","Elles sont copiées dans S3","Elles sont conservées","Elles sont déplacées vers EBS"],answer:0,exp:"Le stockage d'instance est éphémère : il disparaît à l'arrêt."},
{id:"clf-j2-16",q:"Comment un volume EBS est-il sauvegardé ?",choices:["Par des snapshots stockés dans Amazon S3","Par une copie automatique dans une autre région","Par AWS Artifact","Par réplication dans le stockage d'instance"],answer:0,exp:"Les snapshots EBS sont incrémentaux et stockés dans S3."},
{id:"clf-j2-17",q:"Une instance EC2 est dans l'AZ eu-west-3a. Où son volume EBS doit-il se trouver ?",choices:["Dans la même AZ, eu-west-3a","Dans n'importe quelle AZ de la région","Dans n'importe quelle région","Dans une edge location"],answer:0,exp:"Un volume EBS ne s'attache qu'à une instance de la même AZ."},
{id:"clf-j2-18",q:"Comment déplacer les données d'un volume EBS vers une autre AZ ?",choices:["Créer un snapshot puis un nouveau volume dans l'AZ cible","Détacher et rattacher le volume dans l'autre AZ","Activer S3 Transfer Acceleration","Utiliser AWS Direct Connect"],answer:0,exp:"Le snapshot permet de recréer le volume ailleurs."},
{id:"clf-j2-19",q:"Des centaines d'instances EC2 Linux doivent accéder en même temps au même système de fichiers. Quel service choisir ?",choices:["Amazon EFS","Amazon EBS","Le stockage d'instance","Amazon S3 Glacier"],answer:0,exp:"EFS est un système de fichiers NFS partagé entre de nombreuses instances."},
{id:"clf-j2-20",q:"Une entreprise a besoin d'un partage de fichiers Windows (SMB) intégré à Active Directory. Quel service choisir ?",choices:["Amazon FSx for Windows File Server","Amazon EFS","Amazon S3","Amazon EBS"],answer:0,exp:"FSx for Windows offre SMB et l'intégration Active Directory."},
{id:"clf-j2-21",q:"Une simulation de calcul haute performance a besoin d'un système de fichiers très rapide. Quel service est conçu pour cela ?",choices:["Amazon FSx for Lustre","Amazon S3 Glacier","AWS Storage Gateway","Amazon EFS One Zone"],answer:0,exp:"FSx for Lustre vise le calcul haute performance."},
{id:"clf-j2-22",q:"Comment Amazon EFS est-il facturé ?",choices:["Au stockage réellement utilisé","Au stockage provisionné à l'avance","Au nombre d'instances connectées","Par un forfait annuel"],answer:0,exp:"EFS grandit et rétrécit tout seul, on paie ce qu'on utilise."},
{id:"clf-j2-23",q:"Une entreprise veut que ses serveurs sur site accèdent à du stockage AWS tout en gardant un cache local des données récentes. Quel service utiliser ?",choices:["AWS Storage Gateway","AWS Snowball","Amazon EFS","AWS DataSync"],answer:0,exp:"Storage Gateway est une solution hybride avec cache local."},
{id:"clf-j2-24",q:"Une entreprise veut remplacer ses bandes magnétiques de sauvegarde par du stockage cloud sans changer son logiciel de sauvegarde. Quelle option choisir ?",choices:["Storage Gateway Tape Gateway","Amazon EBS","S3 Transfer Acceleration","Amazon FSx for Lustre"],answer:0,exp:"Tape Gateway présente des bandes virtuelles au logiciel existant."},
{id:"clf-j2-25",q:"Une entreprise veut gérer de façon centralisée les sauvegardes d'EBS, RDS, DynamoDB et EFS avec des règles communes. Quel service choisir ?",choices:["AWS Backup","Amazon S3 Glacier","AWS Elastic Disaster Recovery","AWS Config"],answer:0,exp:"AWS Backup centralise et automatise les sauvegardes multi-services."},
{id:"clf-j2-26",q:"Une entreprise veut répliquer en continu ses serveurs sur site vers AWS pour pouvoir redémarrer en quelques minutes après un sinistre. Quel service choisir ?",choices:["AWS Elastic Disaster Recovery","AWS Backup","Amazon S3 Glacier Deep Archive","AWS Storage Gateway Tape Gateway"],answer:0,exp:"DRS réplique en continu et permet une reprise rapide."},
{id:"clf-j2-27",q:"Quel service est une base de données relationnelle managée qui prend en charge MySQL, PostgreSQL, Oracle et SQL Server ?",choices:["Amazon RDS","Amazon DynamoDB","Amazon Neptune","Amazon ElastiCache"],answer:0,exp:"RDS gère plusieurs moteurs relationnels."},
{id:"clf-j2-28",q:"Quel service relationnel, conçu par AWS et compatible MySQL et PostgreSQL, offre des performances supérieures et 6 copies des données sur 3 AZ ?",choices:["Amazon Aurora","Amazon RDS for Oracle","Amazon Redshift","Amazon DocumentDB"],answer:0,exp:"Aurora est la base relationnelle haute performance d'AWS."},
{id:"clf-j2-29",q:"Une application mobile a besoin d'une base NoSQL clé-valeur, sans serveur, avec des latences de quelques millisecondes à n'importe quelle échelle. Quel service choisir ?",choices:["Amazon DynamoDB","Amazon RDS","Amazon Redshift","Amazon Neptune"],answer:0,exp:"DynamoDB est la base NoSQL clé-valeur sans serveur d'AWS."},
{id:"clf-j2-30",q:"Une application veut réduire la charge sur sa base en mettant en cache les requêtes fréquentes, avec des latences de l'ordre de la microseconde. Quel service utiliser ?",choices:["Amazon ElastiCache","Amazon S3","Amazon Redshift","AWS Backup"],answer:0,exp:"ElastiCache est un cache en mémoire (Redis, Memcached)."},
{id:"clf-j2-31",q:"Une application existante utilise MongoDB. Quel service AWS managé est compatible ?",choices:["Amazon DocumentDB","Amazon DynamoDB","Amazon Aurora","Amazon Neptune"],answer:0,exp:"DocumentDB est compatible MongoDB."},
{id:"clf-j2-32",q:"Un réseau social veut stocker et interroger les relations complexes entre utilisateurs (amis d'amis, recommandations). Quel service choisir ?",choices:["Amazon Neptune","Amazon RDS","Amazon ElastiCache","Amazon S3"],answer:0,exp:"Neptune est une base graphe, faite pour les relations."},
{id:"clf-j2-33",q:"Une entreprise veut analyser des pétaoctets de données historiques en SQL pour ses rapports décisionnels. Quel service choisir ?",choices:["Amazon Redshift","Amazon RDS","Amazon DynamoDB","Amazon ElastiCache"],answer:0,exp:"Redshift est l'entrepôt de données d'AWS, fait pour l'analytique."},
{id:"clf-j2-34",q:"Quel avantage principal apporte une base managée (RDS) par rapport à une base installée sur EC2 ?",choices:["AWS gère les correctifs, les sauvegardes et la haute disponibilité","Le client obtient un accès complet à l'OS","La base devient gratuite","Plus besoin de gérer les accès à la base"],answer:0,exp:"Les tâches d'administration sont prises en charge par AWS."},
{id:"clf-j2-35",q:"Une application dépend d'un logiciel qui doit être installé sur le même serveur que la base de données. Quelle option choisir ?",choices:["Installer la base sur Amazon EC2","Amazon RDS","Amazon Aurora Serverless","Amazon DynamoDB"],answer:0,exp:"Seul EC2 donne l'accès à l'OS nécessaire pour installer un logiciel."},
{id:"clf-j2-36",q:"Quelle option RDS assure la haute disponibilité avec une bascule automatique vers une copie de secours dans une autre AZ ?",choices:["RDS Multi-AZ","Les réplicas en lecture (Read Replicas)","Les snapshots manuels","ElastiCache"],answer:0,exp:"Multi-AZ maintient une copie synchrone et bascule automatiquement."},
{id:"clf-j2-37",q:"Une application fait beaucoup plus de lectures que d'écritures et la base RDS sature. Quelle solution améliore les performances de lecture ?",choices:["Ajouter des réplicas en lecture (Read Replicas)","Activer Multi-AZ","Passer en S3 Glacier","Ajouter une NACL"],answer:0,exp:"Les Read Replicas répartissent les lectures sur plusieurs copies."},
{id:"clf-j2-38",q:"Quels services sont des bases de données NoSQL ? (2 réponses)",choices:["Amazon DynamoDB","Amazon DocumentDB","Amazon Aurora","Amazon RDS for PostgreSQL","Amazon Redshift"],answer:0,exp:"DynamoDB est NoSQL clé-valeur."},
{id:"clf-j2-39",q:"Dans le modèle de responsabilité partagée, qui applique les correctifs du moteur de base de données sur Amazon RDS ?",choices:["AWS","Le client","Un partenaire AWS","Personne, ils ne sont pas nécessaires"],answer:0,exp:"Sur RDS, AWS gère l'OS et les correctifs du moteur."},
{id:"clf-j2-40",q:"Une entreprise veut migrer sa base Oracle vers Aurora PostgreSQL. Quels outils utiliser ? (2 réponses)",choices:["AWS Schema Conversion Tool (SCT)","AWS Database Migration Service (DMS)","AWS Snowball","Amazon Athena","AWS Artifact"],answer:0,exp:"SCT convertit le schéma d'un moteur à l'autre."},
{id:"clf-j2-41",q:"Une entreprise veut migrer une base MySQL vers Amazon RDS for MySQL en limitant l'interruption de service. Quel service choisir ?",choices:["AWS DMS","AWS SCT uniquement","AWS Snowball","AWS Backup"],answer:0,exp:"DMS migre la base pendant que la source reste en service."},
{id:"clf-j2-42",q:"Une entreprise doit transférer 500 To vers AWS mais sa connexion internet est lente. Quel service est conçu pour ce cas ?",choices:["AWS Snowball","AWS Site-to-Site VPN","Amazon CloudFront","S3 Transfer Acceleration"],answer:0,exp:"Snowball est un appareil physique, rempli sur site puis renvoyé à AWS."},
{id:"clf-j2-43",q:"Quel service recense les serveurs sur site, leur utilisation et leurs dépendances pour planifier une migration ?",choices:["AWS Application Discovery Service","AWS Migration Hub","AWS DMS","Migration Evaluator"],answer:0,exp:"Application Discovery Service fait l'inventaire et cartographie les dépendances."},
{id:"clf-j2-44",q:"Quel service suit de façon centralisée l'avancement de toutes les migrations d'une entreprise ?",choices:["AWS Migration Hub","AWS Application Migration Service","AWS Snowball","AWS Control Tower"],answer:0,exp:"Migration Hub est le tableau de bord central des migrations."},
{id:"clf-j2-45",q:"Une entreprise veut migrer ses serveurs sur site vers EC2 tels quels (lift & shift) avec une réplication continue. Quel service choisir ?",choices:["AWS Application Migration Service","AWS SCT","Amazon Lightsail","AWS Elastic Beanstalk"],answer:0,exp:"Application Migration Service (MGN) automatise le rehost vers EC2."},
{id:"clf-j2-46",q:"Avant de migrer, une direction veut une estimation des économies possibles (TCO) pour décider. Quel service aide ?",choices:["Migration Evaluator","AWS Migration Hub","AWS Budgets","AWS Cost Explorer"],answer:0,exp:"Migration Evaluator construit le business case de migration."},
{id:"clf-j2-47",q:"Quels services fournissent un système de fichiers partagé ? (2 réponses)",choices:["Amazon EFS","Amazon FSx","Amazon EBS","Amazon S3","Le stockage d'instance"],answer:0,exp:"EFS est un système de fichiers NFS partagé."},
{id:"clf-j2-48",q:"Une application a besoin d'un espace temporaire ultra-rapide pour du cache, et la perte de ces données à l'arrêt n'est pas grave. Quelle option est la plus adaptée ?",choices:["Le stockage d'instance","Amazon EBS Provisioned IOPS","Amazon EFS","Amazon S3 Standard"],answer:0,exp:"Le stockage d'instance est le plus rapide et convient aux données éphémères."},
{id:"clf-j2-49",q:"Comment empêcher qu'un bucket S3 soit rendu public par erreur sur tout un compte ?",choices:["Activer S3 Block Public Access","Activer le versioning","Utiliser S3 One Zone-IA","Activer Transfer Acceleration"],answer:0,exp:"Block Public Access empêche toute exposition publique."},
{id:"clf-j2-50",q:"Quelle base est la plus adaptée à des transactions de commande en ligne (SQL, jointures, cohérence forte) ?",choices:["Amazon Aurora","Amazon Redshift","Amazon Neptune","Amazon S3"],answer:0,exp:"Aurora est relationnel transactionnel, idéal pour les commandes."}
];

window.QDATA[3] = [
{id:"clf-j3-1",q:"Quel composant permet aux ressources d'un VPC de communiquer avec internet ?",choices:["Une Internet Gateway","Un security group","Une NACL","Un VPC endpoint"],answer:0,exp:"L'Internet Gateway est la porte d'entrée et de sortie internet du VPC."},
{id:"clf-j3-2",q:"Des instances dans un sous-réseau privé doivent télécharger des mises à jour sur internet sans être joignables de l'extérieur. Quel composant utiliser ?",choices:["Une NAT Gateway","Une Internet Gateway attachée au sous-réseau privé","AWS Direct Connect","Amazon Route 53"],answer:0,exp:"La NAT Gateway autorise le trafic sortant uniquement."},
{id:"clf-j3-3",q:"Qu'est-ce qui distingue un sous-réseau public d'un sous-réseau privé ?",choices:["Le sous-réseau public a une route vers une Internet Gateway","Le sous-réseau public est gratuit","Le sous-réseau privé n'a pas d'adresses IP","Le sous-réseau public couvre plusieurs AZ"],answer:0,exp:"C'est la table de routage vers l'IGW qui rend un sous-réseau public."},
{id:"clf-j3-4",q:"À quel niveau un security group s'applique-t-il ?",choices:["Au niveau de l'instance (interface réseau)","Au niveau du sous-réseau","Au niveau de la région","Au niveau du compte"],answer:0,exp:"Le security group est un pare-feu attaché à l'instance."},
{id:"clf-j3-5",q:"Une entreprise doit bloquer explicitement une adresse IP malveillante pour tout un sous-réseau. Quel outil utiliser ?",choices:["Une Network ACL","Un security group","AWS Shield Standard","Amazon Inspector"],answer:0,exp:"La NACL accepte des règles de refus explicite au niveau du sous-réseau."},
{id:"clf-j3-6",q:"Quelle affirmation sur les security groups est correcte ?",choices:["Ils sont stateful : la réponse à une requête autorisée est automatiquement permise","Ils sont stateless : il faut autoriser l'aller et le retour","Ils peuvent contenir des règles de refus","Ils s'appliquent à un sous-réseau entier"],answer:0,exp:"Le security group mémorise les connexions (stateful)."},
{id:"clf-j3-7",q:"Quelles caractéristiques s'appliquent aux Network ACL ? (2 réponses)",choices:["Elles sont stateless","Elles prennent en charge les règles d'autorisation et de refus","Elles s'attachent à une instance EC2","Elles sont stateful","Elles ne prennent en charge que les règles d'autorisation"],answer:0,exp:"Il faut autoriser explicitement le trafic de retour."},
{id:"clf-j3-8",q:"Quel service évalue l'accessibilité réseau des instances EC2 et signale les ports exposés inutilement ?",choices:["Amazon Inspector","AWS Shield","Amazon Macie","AWS Artifact"],answer:0,exp:"Inspector analyse les vulnérabilités et l'exposition réseau."},
{id:"clf-j3-9",q:"Une entreprise veut connecter rapidement et à moindre coût son datacenter à son VPC, via une connexion chiffrée sur internet. Quel service choisir ?",choices:["AWS Site-to-Site VPN","AWS Direct Connect","AWS Client VPN","VPC Peering"],answer:0,exp:"Le VPN site à site se met en place en quelques minutes via internet."},
{id:"clf-j3-10",q:"Une entreprise a besoin d'une connexion privée dédiée vers AWS, avec une bande passante constante, qui ne passe pas par internet. Quel service choisir ?",choices:["AWS Direct Connect","AWS Site-to-Site VPN","Amazon CloudFront","AWS Global Accelerator"],answer:0,exp:"Direct Connect est une liaison physique privée dédiée."},
{id:"clf-j3-11",q:"Des employés en télétravail doivent se connecter de façon sécurisée au VPC de l'entreprise depuis leur ordinateur. Quel service choisir ?",choices:["AWS Client VPN","AWS Site-to-Site VPN","AWS Direct Connect","AWS Transit Gateway"],answer:0,exp:"Client VPN connecte des utilisateurs individuels."},
{id:"clf-j3-12",q:"Une entreprise doit interconnecter 50 VPC et plusieurs sites sur site via un point central. Quel service simplifie cette architecture ?",choices:["AWS Transit Gateway","VPC Peering entre chaque paire","Une NAT Gateway","Amazon Route 53"],answer:0,exp:"Transit Gateway fonctionne en étoile (hub) et évite un maillage complexe."},
{id:"clf-j3-13",q:"Le VPC A est appairé au VPC B, et le VPC B au VPC C. Le VPC A peut-il joindre le VPC C via B ?",choices:["Non, le VPC peering n'est pas transitif","Oui, automatiquement","Oui, si les VPC sont dans la même région","Oui, avec une Internet Gateway"],answer:0,exp:"Il faut un peering direct A-C ou un Transit Gateway."},
{id:"clf-j3-14",q:"Une entreprise veut accéder à Amazon S3 depuis son VPC sans que le trafic passe par internet. Quelle solution utiliser ?",choices:["Un VPC endpoint (AWS PrivateLink / endpoint de passerelle)","Une NAT Gateway","Une Internet Gateway","AWS Client VPN"],answer:0,exp:"Un VPC endpoint relie le VPC aux services AWS en privé."},
{id:"clf-j3-15",q:"Quelles fonctions offre Amazon Route 53 ? (2 réponses)",choices:["Service DNS et enregistrement de noms de domaine","Contrôles de santé et routage de basculement (failover)","Mise en cache de contenu statique","Pare-feu applicatif","Stockage objet"],answer:0,exp:"Route 53 est un DNS managé qui vend aussi des domaines."},
{id:"clf-j3-16",q:"Une entreprise veut diriger chaque utilisateur vers la région AWS qui lui répond le plus vite. Quelle politique de routage Route 53 choisir ?",choices:["Routage basé sur la latence","Routage simple","Routage pondéré","Routage par basculement"],answer:0,exp:"Le routage par latence renvoie la région la plus rapide pour l'utilisateur."},
{id:"clf-j3-17",q:"Une équipe veut envoyer 10 % du trafic vers une nouvelle version de son application pour la tester. Quelle politique Route 53 utiliser ?",choices:["Routage pondéré","Routage par géolocalisation","Routage par latence","Routage simple"],answer:0,exp:"Le routage pondéré répartit le trafic selon des pourcentages."},
{id:"clf-j3-18",q:"Un site doit afficher un contenu différent aux utilisateurs situés en France, pour des raisons de licence. Quelle politique Route 53 choisir ?",choices:["Routage par géolocalisation","Routage pondéré","Routage par latence","Routage multivaleur"],answer:0,exp:"La géolocalisation route selon la localisation de l'utilisateur."},
{id:"clf-j3-19",q:"Un site d'actualités veut accélérer l'affichage de ses images et vidéos pour des lecteurs du monde entier. Quel service choisir ?",choices:["Amazon CloudFront","AWS Direct Connect","Amazon Route 53 seul","AWS Transit Gateway"],answer:0,exp:"CloudFront met en cache le contenu au plus près des lecteurs."},
{id:"clf-j3-20",q:"Un jeu en ligne utilise UDP et a besoin de deux adresses IP fixes mondiales et d'un chemin réseau optimisé. Quel service choisir ?",choices:["AWS Global Accelerator","Amazon CloudFront","Amazon API Gateway","AWS Site-to-Site VPN"],answer:0,exp:"Global Accelerator fournit des IP fixes et fait passer le trafic par le réseau AWS, sans cache."},
{id:"clf-j3-21",q:"Quelle différence clé existe entre CloudFront et Global Accelerator ?",choices:["CloudFront met le contenu en cache, Global Accelerator non","Global Accelerator met le contenu en cache, CloudFront non","Les deux sont des DNS","Les deux remplacent Direct Connect"],answer:0,exp:"CloudFront est un CDN avec cache ; Global Accelerator optimise le routage réseau."},
{id:"clf-j3-22",q:"Une équipe veut créer, publier, sécuriser et limiter le nombre d'appels à une API REST qui déclenche des fonctions Lambda. Quel service utiliser ?",choices:["Amazon API Gateway","Amazon CloudFront","Elastic Load Balancing","AWS AppSync uniquement pour REST"],answer:0,exp:"API Gateway gère le cycle de vie complet des API."},
{id:"clf-j3-23",q:"Une entreprise veut analyser des photos pour détecter des visages et des objets. Quel service choisir ?",choices:["Amazon Rekognition","Amazon Textract","Amazon Polly","Amazon Comprehend"],answer:0,exp:"Rekognition analyse les images et vidéos."},
{id:"clf-j3-24",q:"Une compagnie d'assurance veut extraire automatiquement les champs de formulaires et de factures scannés. Quel service choisir ?",choices:["Amazon Textract","Amazon Rekognition","Amazon Translate","Amazon Lex"],answer:0,exp:"Textract extrait texte, formulaires et tableaux des documents."},
{id:"clf-j3-25",q:"Une marque veut savoir si les avis de ses clients sont positifs ou négatifs. Quel service choisir ?",choices:["Amazon Comprehend","Amazon Transcribe","Amazon Polly","Amazon Kendra"],answer:0,exp:"Comprehend fait de l'analyse de sentiment sur du texte."},
{id:"clf-j3-26",q:"Un centre d'appels veut convertir automatiquement les enregistrements audio en texte. Quel service choisir ?",choices:["Amazon Transcribe","Amazon Polly","Amazon Translate","Amazon Textract"],answer:0,exp:"Transcribe fait de la reconnaissance vocale (voix vers texte)."},
{id:"clf-j3-27",q:"Un site d'actualités veut proposer une version audio de ses articles. Quel service choisir ?",choices:["Amazon Polly","Amazon Transcribe","Amazon Comprehend","Amazon Rekognition"],answer:0,exp:"Polly synthétise une voix à partir de texte."},
{id:"clf-j3-28",q:"Une entreprise veut créer un chatbot vocal et textuel pour son service client. Quel service choisir ?",choices:["Amazon Lex","Amazon Polly","Amazon Kendra","Amazon Comprehend"],answer:0,exp:"Lex construit des interfaces conversationnelles (la technologie d'Alexa)."},
{id:"clf-j3-29",q:"Une entreprise veut un moteur de recherche intelligent sur ses documents internes (wikis, PDF, intranet). Quel service choisir ?",choices:["Amazon Kendra","Amazon Athena","Amazon Translate","Amazon Textract"],answer:0,exp:"Kendra est un service de recherche d'entreprise basé sur le machine learning."},
{id:"clf-j3-30",q:"Une équipe de data scientists veut construire, entraîner et déployer ses propres modèles de machine learning. Quel service choisir ?",choices:["Amazon SageMaker AI","Amazon Rekognition","Amazon Lex","Amazon QuickSight"],answer:0,exp:"SageMaker AI est la plateforme complète pour des modèles sur mesure."},
{id:"clf-j3-31",q:"Un site e-commerce doit être disponible en 12 langues. Quel service automatise la traduction ?",choices:["Amazon Translate","Amazon Transcribe","Amazon Polly","Amazon Comprehend"],answer:0,exp:"Translate fait de la traduction automatique."},
{id:"clf-j3-32",q:"Quel service d'IA générative d'AWS aide les employés à obtenir des réponses à partir des données de l'entreprise et aide les développeurs à coder ?",choices:["Amazon Q","Amazon Kendra","Amazon Lex","Amazon Athena"],answer:0,exp:"Amazon Q (Business et Developer) est l'assistant d'IA générative d'AWS."},
{id:"clf-j3-33",q:"Une équipe veut interroger en SQL des fichiers de logs stockés dans S3, sans charger les données dans une base et sans serveur. Quel service choisir ?",choices:["Amazon Athena","Amazon Redshift","Amazon RDS","Amazon Kinesis"],answer:0,exp:"Athena exécute du SQL directement sur S3, à la demande."},
{id:"clf-j3-34",q:"Une entreprise doit collecter et traiter en temps réel des millions d'événements de clics sur son site. Quel service choisir ?",choices:["Amazon Kinesis","Amazon Athena","AWS Glue","Amazon S3 Glacier"],answer:0,exp:"Kinesis est fait pour les flux de données en temps réel."},
{id:"clf-j3-35",q:"Avant l'analyse, des données doivent être extraites, nettoyées et transformées automatiquement, sans serveur. Quel service choisir ?",choices:["AWS Glue","Amazon QuickSight","Amazon Kinesis","Amazon Neptune"],answer:0,exp:"Glue est le service ETL sans serveur d'AWS, avec un catalogue de données."},
{id:"clf-j3-36",q:"La direction veut des tableaux de bord interactifs de business intelligence. Quel service choisir ?",choices:["Amazon QuickSight","Amazon Athena","AWS Glue","Amazon EMR"],answer:0,exp:"QuickSight est le service de BI et de tableaux de bord."},
{id:"clf-j3-37",q:"Une entreprise veut exécuter des traitements Apache Spark et Hadoop sur de très gros volumes. Quel service managé choisir ?",choices:["Amazon EMR","Amazon QuickSight","Amazon Athena","Amazon ElastiCache"],answer:0,exp:"EMR est la plateforme big data managée (Spark, Hadoop)."},
{id:"clf-j3-38",q:"Quel service permet la recherche plein texte et l'analyse de logs, basé sur un moteur open source ?",choices:["Amazon OpenSearch Service","Amazon Kendra","Amazon Redshift","AWS Glue"],answer:0,exp:"OpenSearch Service sert à la recherche et à l'analyse de logs."},
{id:"clf-j3-39",q:"Une application doit découpler son front-end de son traitement des commandes pour qu'aucune commande ne soit perdue lors des pics. Quel service choisir ?",choices:["Amazon SQS","Amazon SNS","Amazon SES","Amazon Connect"],answer:0,exp:"SQS met les messages en file d'attente jusqu'à leur traitement."},
{id:"clf-j3-40",q:"Une alarme doit notifier une équipe par e-mail et SMS, et déclencher en même temps une fonction Lambda. Quel service choisir ?",choices:["Amazon SNS","Amazon SQS","AWS Step Functions","Amazon SES"],answer:0,exp:"SNS publie un message vers plusieurs abonnés (e-mail, SMS, Lambda)."},
{id:"clf-j3-41",q:"Une équipe veut déclencher automatiquement une action chaque fois qu'une instance EC2 change d'état, ou lancer une tâche tous les jours à 2 h. Quel service choisir ?",choices:["Amazon EventBridge","Amazon SQS","Amazon SES","AWS X-Ray"],answer:0,exp:"EventBridge réagit aux événements et planifie des tâches."},
{id:"clf-j3-42",q:"Une équipe doit enchaîner plusieurs fonctions Lambda dans un workflow avec des conditions et des reprises en cas d'erreur. Quel service choisir ?",choices:["AWS Step Functions","Amazon SNS","Amazon Kinesis","AWS CodeBuild"],answer:0,exp:"Step Functions orchestre visuellement des workflows."},
{id:"clf-j3-43",q:"Une entreprise veut envoyer des e-mails marketing et transactionnels à des milliers de clients. Quel service choisir ?",choices:["Amazon SES","Amazon SNS","Amazon SQS","Amazon Connect"],answer:0,exp:"SES est le service d'envoi d'e-mails en masse."},
{id:"clf-j3-44",q:"Une entreprise veut mettre en place un centre de contact téléphonique dans le cloud. Quel service choisir ?",choices:["Amazon Connect","Amazon Lex seul","Amazon SES","Amazon WorkSpaces"],answer:0,exp:"Connect est le centre de contact cloud d'AWS."},
{id:"clf-j3-45",q:"Une entreprise veut fournir des bureaux Windows complets à ses employés, accessibles depuis n'importe quel appareil. Quel service choisir ?",choices:["Amazon WorkSpaces","Amazon AppStream 2.0","Amazon Lightsail","AWS Client VPN"],answer:0,exp:"WorkSpaces fournit des bureaux virtuels complets."},
{id:"clf-j3-46",q:"Un éditeur de logiciel veut diffuser une seule application de conception dans le navigateur de ses clients, sans installation. Quel service choisir ?",choices:["Amazon AppStream 2.0","Amazon WorkSpaces","AWS Amplify","Amazon CloudFront"],answer:0,exp:"AppStream 2.0 diffuse des applications vers un navigateur."},
{id:"clf-j3-47",q:"Quel service orchestre une chaîne CI/CD complète, de la source au déploiement ?",choices:["AWS CodePipeline","AWS CodeBuild","AWS X-Ray","AWS CLI"],answer:0,exp:"CodePipeline automatise l'ensemble du pipeline de livraison."},
{id:"clf-j3-48",q:"Une application distribuée est lente et l'équipe veut savoir quel composant ralentit les requêtes. Quel service utiliser ?",choices:["AWS X-Ray","AWS CloudTrail","AWS CodeBuild","Amazon Inspector"],answer:0,exp:"X-Ray trace les requêtes à travers les composants."},
{id:"clf-j3-49",q:"Une startup veut construire et héberger rapidement une application web et mobile full-stack. Quel service choisir ?",choices:["AWS Amplify","AWS IoT Core","Amazon AppStream 2.0","AWS Batch"],answer:0,exp:"Amplify sert à construire et héberger des applis web et mobiles."},
{id:"clf-j3-50",q:"Une usine veut connecter et gérer de façon sécurisée des milliers de capteurs. Quel service choisir ?",choices:["AWS IoT Core","Amazon Kinesis seul","Amazon Connect","AWS Amplify"],answer:0,exp:"IoT Core connecte et gère des objets connectés."}
];

window.QDATA[4] = [
{id:"clf-j4-1",q:"Selon le modèle de responsabilité partagée, de quoi AWS est-il responsable ?",choices:["De la sécurité DU cloud","De la sécurité DANS le cloud","Des données du client","Des comptes IAM du client"],answer:0,exp:"AWS protège l'infrastructure : datacenters, matériel, réseau, hyperviseur."},
{id:"clf-j4-2",q:"Quelles tâches relèvent du client sur Amazon EC2 ? (2 réponses)",choices:["Appliquer les correctifs de l'OS invité","Configurer les security groups","Assurer la sécurité physique des datacenters","Maintenir l'hyperviseur","Remplacer les disques défectueux"],answer:0,exp:"Sur EC2 (IaaS), l'OS appartient au client."},
{id:"clf-j4-3",q:"Qui est responsable de la destruction sécurisée des disques de stockage en fin de vie ?",choices:["AWS","Le client","Un auditeur tiers","Le partenaire AWS du client"],answer:0,exp:"Le matériel physique et son cycle de vie relèvent d'AWS."},
{id:"clf-j4-4",q:"Sur AWS Lambda, de quoi le client reste-t-il responsable ?",choices:["Du code de la fonction et des permissions IAM","Des correctifs de l'OS","De la mise à l'échelle des serveurs","Du runtime d'exécution"],answer:0,exp:"Le client gère son code, ses données et ses permissions."},
{id:"clf-j4-5",q:"Sur Amazon DynamoDB, quelle responsabilité incombe au client ?",choices:["Gérer qui a accès aux tables","Appliquer les correctifs du service","Assurer la sécurité physique","Gérer le matériel de stockage"],answer:0,exp:"Les accès (IAM) restent au client sur tout service."},
{id:"clf-j4-6",q:"Quels contrôles sont considérés comme partagés entre AWS et le client ? (2 réponses)",choices:["La gestion des correctifs","La sensibilisation et la formation","La sécurité physique des datacenters","Les contrôles environnementaux","Le chiffrement du réseau mondial AWS"],answer:0,exp:"AWS corrige l'infrastructure, le client corrige ses OS invités et ses applis."},
{id:"clf-j4-7",q:"Plus un service est managé (par exemple Lambda par rapport à EC2), que se passe-t-il ?",choices:["AWS prend en charge davantage de responsabilités","Le client prend en charge davantage de responsabilités","Les responsabilités restent identiques","Le client n'a plus aucune responsabilité"],answer:0,exp:"Avec un service managé, AWS gère l'OS, le runtime, la mise à l'échelle."},
{id:"clf-j4-8",q:"Qui décide d'activer le chiffrement des données au repos dans un bucket S3 ?",choices:["Le client","AWS","Un partenaire certifié","AWS Support"],answer:0,exp:"AWS fournit les outils, le client choisit et configure la protection de ses données."},
{id:"clf-j4-9",q:"Sur Amazon RDS, quelle tâche reste à la charge du client ?",choices:["Gérer les utilisateurs et les droits de la base de données","Appliquer les correctifs de l'OS sous-jacent","Remplacer le matériel défectueux","Maintenir l'hyperviseur"],answer:0,exp:"Les comptes et permissions de la base relèvent du client."},
{id:"clf-j4-10",q:"Quel principe consiste à n'accorder que les permissions strictement nécessaires à une tâche ?",choices:["Le principe du moindre privilège","La responsabilité partagée","La défense en profondeur","L'élasticité"],answer:0,exp:"C'est la définition du moindre privilège."},
{id:"clf-j4-11",q:"Une application sur EC2 doit écrire dans un bucket S3. Quelle est la méthode recommandée ?",choices:["Attacher un rôle IAM à l'instance","Stocker des clés d'accès dans le code","Stocker des clés d'accès dans un fichier sur l'instance","Rendre le bucket public"],answer:0,exp:"Le rôle fournit des identifiants temporaires renouvelés automatiquement."},
{id:"clf-j4-12",q:"20 développeurs ont besoin des mêmes permissions. Quelle est la meilleure pratique ?",choices:["Les placer dans un groupe IAM auquel on attache une policy","Attacher une policy individuelle à chacun","Leur partager un seul utilisateur IAM","Leur donner les identifiants root"],answer:0,exp:"Un groupe centralise les permissions et simplifie la gestion."},
{id:"clf-j4-13",q:"Quelle affirmation sur les groupes IAM est correcte ?",choices:["Un groupe ne peut contenir que des utilisateurs","Un groupe peut contenir d'autres groupes","Un groupe peut contenir des rôles","Un groupe peut se connecter à la console"],answer:0,exp:"Les groupes IAM ne contiennent que des users."},
{id:"clf-j4-14",q:"Dans IAM, que se passe-t-il quand une policy autorise une action et qu'une autre la refuse explicitement ?",choices:["Le refus explicite l'emporte","L'autorisation l'emporte","La policy la plus récente l'emporte","AWS demande une confirmation"],answer:0,exp:"Un Deny explicite prime toujours sur un Allow."},
{id:"clf-j4-15",q:"Quel format utilisent les policies IAM ?",choices:["JSON","XML","YAML uniquement","CSV"],answer:0,exp:"Les policies IAM sont des documents JSON."},
{id:"clf-j4-16",q:"Un utilisateur du compte A doit accéder à des ressources du compte B. Quelle est la méthode recommandée ?",choices:["Créer un rôle IAM dans le compte B que l'utilisateur du compte A peut endosser","Créer un nouvel utilisateur IAM dans le compte B et partager le mot de passe","Partager les identifiants root du compte B","Fusionner les deux comptes"],answer:0,exp:"Le rôle inter-comptes donne un accès temporaire et contrôlé."},
{id:"clf-j4-17",q:"Quelles sont les bonnes pratiques pour protéger l'utilisateur root ? (2 réponses)",choices:["Activer la MFA sur le compte root","Ne pas créer de clés d'accès pour le root","Utiliser le root pour les tâches quotidiennes","Partager le mot de passe root avec l'équipe d'admins","Désactiver complètement le root"],answer:0,exp:"La MFA protège contre le vol du mot de passe."},
{id:"clf-j4-18",q:"Quelle tâche ne peut être effectuée QUE par l'utilisateur root ?",choices:["Changer le plan AWS Support","Créer un bucket S3","Lancer une instance EC2","Créer un utilisateur IAM"],answer:0,exp:"Modifier ou annuler le plan de support est réservé au root."},
{id:"clf-j4-19",q:"Quelles tâches sont réservées à l'utilisateur root ? (2 réponses)",choices:["Fermer le compte AWS","Modifier l'adresse e-mail du compte","Créer un groupe IAM","Consulter Cost Explorer","Créer une policy IAM"],answer:0,exp:"La fermeture du compte exige le root."},
{id:"clf-j4-20",q:"Quel service permet aux employés de se connecter une seule fois pour accéder à plusieurs comptes AWS et applications métier ?",choices:["AWS IAM Identity Center","Amazon Cognito","AWS Secrets Manager","AWS Artifact"],answer:0,exp:"IAM Identity Center (ex-AWS SSO) fournit l'authentification unique."},
{id:"clf-j4-21",q:"Une application mobile doit permettre à ses utilisateurs de s'inscrire et de se connecter avec Google ou Facebook. Quel service choisir ?",choices:["Amazon Cognito","AWS IAM Identity Center","AWS Directory Service","Des utilisateurs IAM pour chaque client"],answer:0,exp:"Cognito gère l'authentification des utilisateurs finaux d'une appli."},
{id:"clf-j4-22",q:"Une entreprise veut stocker les mots de passe de ses bases de données avec une rotation automatique. Quel service choisir ?",choices:["AWS Secrets Manager","AWS KMS","Amazon Macie","AWS Artifact"],answer:0,exp:"Secrets Manager stocke les secrets et automatise leur rotation."},
{id:"clf-j4-23",q:"Une équipe veut stocker des paramètres de configuration de façon centralisée et peu coûteuse. Quel service convient ?",choices:["AWS Systems Manager Parameter Store","Amazon S3 Glacier","AWS CloudHSM","Amazon Inspector"],answer:0,exp:"Parameter Store stocke des paramètres et des secrets simples."},
{id:"clf-j4-24",q:"Une entreprise veut que ses employés utilisent leurs identifiants Active Directory existants pour accéder à AWS, sans créer d'utilisateurs IAM. Comment s'appelle ce mécanisme ?",choices:["La fédération d'identités","Le principe du moindre privilège","La facturation consolidée","Le chiffrement en transit"],answer:0,exp:"La fédération permet d'utiliser un fournisseur d'identité externe (SAML, AD)."},
{id:"clf-j4-25",q:"Quels éléments renforcent l'authentification sur AWS ? (2 réponses)",choices:["L'authentification multifacteur (MFA)","Une politique de mots de passe exigeante","Le partage de comptes entre collègues","Des clés d'accès qui n'expirent jamais","Un bucket S3 public"],answer:0,exp:"La MFA ajoute un second facteur."},
{id:"clf-j4-26",q:"Quel rapport IAM liste tous les utilisateurs et l'état de leurs identifiants (MFA, âge des clés, dernière utilisation) ?",choices:["Le credential report","Le rapport d'utilisation et de coût","AWS Artifact","Le tableau de bord AWS Health"],answer:0,exp:"Le credential report recense l'état des identifiants de chaque utilisateur."},
{id:"clf-j4-27",q:"Une policy écrite par AWS, prête à l'emploi et maintenue par AWS, s'appelle :",choices:["Une policy gérée par AWS","Une policy inline","Une policy gérée par le client","Une SCP"],answer:0,exp:"Les policies gérées par AWS sont créées et mises à jour par AWS."},
{id:"clf-j4-28",q:"Quel service protège gratuitement et automatiquement toutes les applications AWS contre les attaques DDoS les plus courantes ?",choices:["AWS Shield Standard","AWS Shield Advanced","AWS WAF","Amazon GuardDuty"],answer:0,exp:"Shield Standard est gratuit et activé pour tous."},
{id:"clf-j4-29",q:"Une entreprise veut une équipe de réponse aux attaques DDoS disponible 24/7 et une protection contre les surcoûts dus à une attaque. Quel service choisir ?",choices:["AWS Shield Advanced","AWS Shield Standard","AWS Firewall Manager","Amazon Inspector"],answer:0,exp:"Shield Advanced inclut l'équipe de réponse DDoS et la protection des coûts."},
{id:"clf-j4-30",q:"Une application web subit des tentatives d'injection SQL et de cross-site scripting. Quel service les bloque ?",choices:["AWS WAF","AWS Shield Standard","Amazon Macie","Network ACL"],answer:0,exp:"WAF filtre les requêtes HTTP malveillantes (couche 7)."},
{id:"clf-j4-31",q:"Une entreprise avec 40 comptes AWS veut appliquer les mêmes règles WAF et security groups partout, de façon centralisée. Quel service choisir ?",choices:["AWS Firewall Manager","AWS WAF seul dans chaque compte","Amazon GuardDuty","AWS Trusted Advisor"],answer:0,exp:"Firewall Manager centralise les règles sur tous les comptes d'une organisation."},
{id:"clf-j4-32",q:"Quel service utilise le machine learning sur CloudTrail, les VPC Flow Logs et les journaux DNS pour détecter une activité malveillante ?",choices:["Amazon GuardDuty","Amazon Inspector","Amazon Macie","AWS Config"],answer:0,exp:"GuardDuty est le service de détection de menaces."},
{id:"clf-j4-33",q:"Une entreprise veut scanner automatiquement ses instances EC2 et ses images de conteneurs pour trouver des vulnérabilités logicielles connues (CVE). Quel service choisir ?",choices:["Amazon Inspector","Amazon GuardDuty","AWS Shield","Amazon Detective"],answer:0,exp:"Inspector scanne les vulnérabilités logicielles."},
{id:"clf-j4-34",q:"Une entreprise veut découvrir automatiquement les données personnelles et numéros de carte bancaire stockés dans ses buckets S3. Quel service choisir ?",choices:["Amazon Macie","Amazon Inspector","AWS WAF","AWS KMS"],answer:0,exp:"Macie identifie les données sensibles dans S3."},
{id:"clf-j4-35",q:"Après une alerte GuardDuty, l'équipe sécurité veut analyser et visualiser la cause de l'incident. Quel service utiliser ?",choices:["Amazon Detective","AWS Artifact","AWS Shield","Amazon Macie"],answer:0,exp:"Detective aide à enquêter sur l'origine d'un incident."},
{id:"clf-j4-36",q:"Quel service regroupe dans un tableau de bord central les alertes de GuardDuty, Inspector, Macie et vérifie le respect des bonnes pratiques ?",choices:["AWS Security Hub","Amazon Detective","AWS Firewall Manager","AWS Config"],answer:0,exp:"Security Hub centralise les résultats de sécurité."},
{id:"clf-j4-37",q:"Quel service permet de créer et gérer les clés utilisées pour chiffrer les données au repos dans S3, EBS et RDS ?",choices:["AWS KMS","AWS Certificate Manager","AWS Secrets Manager","Amazon Macie"],answer:0,exp:"KMS gère les clés de chiffrement, intégré à la plupart des services."},
{id:"clf-j4-38",q:"Une réglementation exige que l'entreprise ait le contrôle exclusif de ses clés, sur un matériel dédié auquel AWS n'a pas accès. Quel service choisir ?",choices:["AWS CloudHSM","AWS KMS avec clés gérées par AWS","AWS Secrets Manager","AWS Certificate Manager"],answer:0,exp:"CloudHSM fournit un module matériel dédié contrôlé par le client seul."},
{id:"clf-j4-39",q:"Quel service fournit gratuitement des certificats SSL/TLS publics avec renouvellement automatique ?",choices:["AWS Certificate Manager (ACM)","AWS KMS","AWS CloudHSM","AWS Artifact"],answer:0,exp:"ACM émet et renouvelle les certificats publics."},
{id:"clf-j4-40",q:"Comment protéger les données qui circulent entre le navigateur d'un utilisateur et un site web hébergé sur AWS ?",choices:["Chiffrement en transit avec TLS","Chiffrement au repos avec KMS","Activer le versioning S3","Utiliser S3 Glacier"],answer:0,exp:"TLS (HTTPS) chiffre les données pendant leur transfert."},
{id:"clf-j4-41",q:"Quels sont les deux types de chiffrement à connaître sur AWS ? (2 réponses)",choices:["Chiffrement au repos","Chiffrement en transit","Chiffrement en mémoire cache","Chiffrement par région","Chiffrement par edge location"],answer:0,exp:"Il protège les données stockées."},
{id:"clf-j4-42",q:"Où une entreprise peut-elle trouver des produits de sécurité d'éditeurs tiers (pare-feux, antivirus) prêts à déployer sur AWS ?",choices:["AWS Marketplace","AWS Artifact","AWS Trusted Advisor","AWS Health Dashboard"],answer:0,exp:"Marketplace propose des logiciels tiers, dont des produits de sécurité."},
{id:"clf-j4-43",q:"Quelles sources officielles d'information sur la sécurité AWS existe-t-il ? (2 réponses)",choices:["AWS Security Blog","AWS Security Center","Un forum non officiel de dumps","AWS Artifact pour les tickets","Amazon Macie"],answer:0,exp:"Le blog sécurité publie les nouveautés et bonnes pratiques."},
{id:"clf-j4-44",q:"Quel service signale par exemple que la MFA n'est pas activée sur le root ou que des ports sont ouverts à tous ?",choices:["AWS Trusted Advisor","AWS Artifact","Amazon Polly","AWS Batch"],answer:0,exp:"Trusted Advisor inclut des contrôles de sécurité de base."},
{id:"clf-j4-45",q:"Quel service permet de partager des sous-réseaux ou un Transit Gateway avec d'autres comptes AWS ?",choices:["AWS Resource Access Manager (RAM)","AWS Organizations SCP","AWS IAM Identity Center","AWS Artifact"],answer:0,exp:"RAM partage des ressources entre comptes."},
{id:"clf-j4-46",q:"Quelle différence y a-t-il entre GuardDuty et Inspector ?",choices:["GuardDuty détecte des comportements suspects, Inspector des failles logicielles","GuardDuty chiffre les données, Inspector les sauvegarde","Les deux protègent des DDoS","Inspector analyse les logs DNS, GuardDuty les CVE"],answer:0,exp:"C'est exactement la distinction à retenir."},
{id:"clf-j4-47",q:"Quels services protègent une application web exposée sur internet ? (2 réponses)",choices:["AWS WAF","AWS Shield","AWS Batch","Amazon Polly","AWS Glue"],answer:0,exp:"WAF filtre les requêtes malveillantes."},
{id:"clf-j4-48",q:"Dans le modèle de responsabilité partagée, que sont les contrôles hérités ?",choices:["Les contrôles physiques et environnementaux qu'AWS assure et dont le client bénéficie","Les permissions IAM transmises d'un groupe à ses membres","Les règles de pare-feu copiées entre comptes","Les sauvegardes conservées après la fermeture d'un compte"],answer:0,exp:"Le client hérite des contrôles qu'AWS met en place sur l'infrastructure."},
{id:"clf-j4-49",q:"Une instance EC2 doit lire une table DynamoDB. Quelle identité IAM lui attacher ?",choices:["Un rôle IAM avec une policy limitée à cette table","Un utilisateur IAM avec des clés stockées sur l'instance","Le compte root","Un groupe IAM"],answer:0,exp:"Le rôle fournit des identifiants temporaires, limités au besoin (moindre privilège)."},
{id:"clf-j4-50",q:"Quelle affirmation sur AWS Shield Standard est correcte ?",choices:["Il est inclus sans coût supplémentaire pour tous les clients AWS","Il nécessite le plan de support Enterprise","Il inclut une équipe de réponse DDoS 24/7","Il protège contre les injections SQL"],answer:0,exp:"Shield Standard est automatique et gratuit."}
];

